window.products.push({"id":1099276,"name":"Ez4garden Reuseable Heavy Duty Garden Leaf Waste Bag Yard Compost Bin Composting Fruit Kitchen Waste Fermentation Cali Secrets Growers 40L,Dark Green","category":"homeandappliances","retail price":26.99,"sale price":null,"image":"https://m.media-amazon.com/images/I/410oU4EhITL._AC_.jpg","description":"The composter bag will allow you to ferment all of your kitchen waste including meats, cheese, bread, and veggies. The lid seals in odors and keeps pests out. The container can easily get compost from under door. Great for fruit fermentation to add flavors to your flowers.This composting bag keeps things odor-free and easy by letting you easily scoop scraps into it,which is a mess-free way to keep scraps until you're ready to take them to your nearest collection center.","images":["https://m.media-amazon.com/images/I/410oU4EhITL._AC_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Ez4garden","source_asin":"B0BHQ9C38B","category_path":"Home & Kitchen"},"sku":"BM-1099276","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B0BHQ9C38B","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B0BHQ9C38B","price_pending":true,"merchant_ready":false});
