window.products.push({"id":1099466,"name":"TEEWAL Horse Statue, Horseshoe Decor, Horseshoe Art, Horse Gift, Equestrian Gift, Horse Decor, Horse Sculpture, Horse Shoe Art, Iron Black","category":"homeandappliances","retail price":20.99,"sale price":null,"image":"https://m.media-amazon.com/images/I/61N4yaqAIIL._AC_.jpg","description":"Introducing our unique Horseshoe Statue, perfect for creating a warm and inviting entrance to your garden or as a charming addition to any room in your home. Crafted in the shape of a crescent moon, it symbolizes the image of a great mother and the creator of life. As a symbol of luck, this statue is a wonderful gift for loved ones and can be displayed both indoors and outdoors, adding a beautiful touch of scenery to any space. Plus, it's the perfect reminder of good fortune to carry with you throughout your everyday life.","images":["https://m.media-amazon.com/images/I/61N4yaqAIIL._AC_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"TEEWAL","source_asin":"B09TJG3Z97","category_path":"Home & Kitchen"},"sku":"BM-1099466","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B09TJG3Z97","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B09TJG3Z97","price_pending":true,"merchant_ready":false});
